function scrollToY(e){window.scrollTo({top:e,behavior:"smooth"})}window.addEventListener("load",function(){let o=document.querySelector(".page-header"),e=document.querySelectorAll(".animation-up, .animation-left, .animation-right, .animation-show");function t(){let o=window.innerHeight;e.forEach(e=>{e.getBoundingClientRect().top<o-10&&(e.style.opacity="1",e.style.transform="translateY(0)")})}scrollToY(0),t(),window.addEventListener("scroll",function(e){72<window.pageYOffset?o.classList.add("page-header__scroll"):o.classList.remove("page-header__scroll"),t()})});